SELECT 
FROM iam_tenant_context_switches
WHERE family_id = #{familyId} AND idempotency_key = #{idempotencyKey}

mapper.update:
UPDATE iam_tenant_context_switches
SET recovery_exhausted_at = #{now}, next_attempt_at = #{now},
    lease_owner = NULL, lease_until = NULL, last_failure = #{failureSummary}
WHERE switch_status = 'PENDING'
  AND recovery_exhausted_at IS NULL
  AND attempt_count >= #{maximumAttempts}
  AND next_attempt_at <= #{now}
  AND (lease_until IS NULL OR lease_until <= #{now})

UPDATE iam_tenant_context_switches
SET recovery_exhausted_at = #{now}, next_attempt_at = #{now},
    lease_owner = NULL, lease_until = NULL, last_failure = #{failureSummary}
WHERE id = #{workflowId}
  AND switch_status = 'PENDING'
  AND recovery_exhausted_at IS NULL
  AND attempt_count >= #{maximumAttempts}
  AND next_attempt_at <= #{now}
  AND (lease_until IS NULL OR lease_until <= #{now})

mapper.select:
UPDATE iam_tenant_context_switches
SET attempt_count = attempt_count + 1,
    lease_owner = #{claimant}, lease_until = #{claimedUntil}
WHERE id = #{workflowId}
  AND switch_status = 'PENDING'
  AND recovery_exhausted_at IS NULL
  AND attempt_count < #{maximumAttempts}
  AND next_attempt_at <= #{now}
  AND (lease_until IS NULL OR lease_until <= #{now})
RETURNING

mapper.update:
UPDATE iam_tenant_context_switches
SET next_attempt_at = #{retryAt}, lease_owner = NULL, lease_until = NULL,
    last_failure = #{failureSummary}
WHERE id = #{workflowId} AND switch_status = 'PENDING'
  AND lease_owner = #{claimant} AND attempt_count = #{attemptCount}

UPDATE iam_tenant_context_switches
SET recovery_exhausted_at = #{exhaustedAt}, next_attempt_at = #{exhaustedAt},
    lease_owner = NULL, lease_until = NULL, last_failure = #{failureSummary}
WHERE id = #{workflowId} AND switch_status = 'PENDING'
  AND lease_owner = #{claimant} AND attempt_count = #{attemptCount}

UPDATE iam_tenant_context_switches
SET switch_status = 'AWAITING_REFRESH', result_http_status = 204, completed_at = #{completedAt},
    lease_owner = NULL, lease_until = NULL, last_failure = NULL
WHERE id = #{workflowId}
  AND switch_status = 'PENDING'
  AND expected_context_version = #{expectedContextVersion}
  AND attempt_count = #{attemptCount}

UPDATE iam_tenant_context_switches
SET switch_status = #{switchStatus}, refreshed_at = #{refreshedAt}
WHERE family_id = #{familyId}
  AND switch_status = 'AWAITING_REFRESH'
  AND expected_context_version + 1 = #{contextVersion}
